const loaders={map:()=>import("./map-data.js"),cuisines:()=>import("./cuisines-data.js"),festivals:()=>import("./festivals-data.js"),culture:()=>import("./culture-data.js"),quiz:()=>import("./quiz-data.js")};export function hasDataModule(a){return Object.prototype.hasOwnProperty.call(loaders,a)}export async function loadDataModule(a){if(!hasDataModule(a))throw new Error(`Unknown data module: ${a}`);return loaders[a]()}export async function loadDataModules(a=[]){const t=await Promise.all(a.filter(hasDataModule).map(async a=>[a,await loadDataModule(a)]));return Object.fromEntries(t)}